WITH base AS (SELECT id, order_id, method, amount, paid_at, status, CEIL(amount) amount_whole, UPPER(status) status_upper FROM payments WHERE paid_at >= TO_DATE('2023-08-20') AND order_id IS NOT NULL) SELECT status, CASE WHEN amount >= 1700 THEN 'HIGH' ELSE 'LOW' END AS amount_tier, COUNT(DISTINCT status) AS distinct_status, MIN(paid_at) AS first_paid_at FROM base GROUP BY status, CASE WHEN amount >= 1700 THEN 'HIGH' ELSE 'LOW' END ORDER BY status NULLS LAST;
